const RPRE=()=>[['open',L('Open','مفتوحة'),openR],['critical',L('Critical / high','حرجة / عالية'),r=>openR(r)&&['critical','high'].includes(r.impact)],['blockers',L('Blockers','العوائق'),r=>openR(r)&&r.type==='blocker'],['overdue',L('Past target date','تجاوزت التاريخ المستهدف'),riskOverdue],['escalate',L('Escalated','مصعّدة'),r=>openR(r)&&r.escalation],['client',L('Pending client','بانتظار العميل'),r=>openR(r)&&r.party==='client'],['internal',L('Internal team','الفريق الداخلي'),r=>openR(r)&&r.party==='internal'],['vendor',L('Vendor','المورّد'),r=>openR(r)&&r.party==='vendor'],['management',L('Management decision','قرار الإدارة'),r=>openR(r)&&r.party==='management'],['resolved',L('Resolved / closed','محلولة / مغلقة'),r=>!openR(r)]];
