function risksTable(list,inEng){if(!list.length)return `<div class="empty">${L('Nothing here.','لا يوجد شيء هنا.')}</div>`;
  list=list.slice().sort((a,b)=>(openR(b)-openR(a))||PRIO.findIndex(p=>p[0]===b.impact)-PRIO.findIndex(p=>p[0]===a.impact));
  return `<div class="card" style="padding:0;overflow:auto"><table class="leads"><thead><tr><th>${L('Title','العنوان')}</th>${inEng?'':`<th>${L('Account / engagement','الحساب / الارتباط')}</th>`}<th>${L('Type','النوع')}</th><th>${L('Impact','التأثير')}</th><th>${L('Who must act','من عليه التصرف')}</th><th>${L('Owner','المسؤول')}</th><th>${L('Target','المستهدف')}</th><th>${L('Status','الحالة')}</th></tr></thead><tbody>
  ${list.map(r=>`<tr class="${riskOverdue(r)?'od':''}" onclick="riskForm('${r.id}')"><td><span class="small muted">${esc(r.code||'')}</span> <b class="lk">${esc(r.title)}</b>${r.escalation&&openR(r)?' <span class="spill" style="--c:#C0392B">⬆ '+L('Escalated','مصعّد')+'</span>':''}</td>${inEng?'':`<td class="small">${esc(r.clientName||'')}<div class="muted">${esc(r.engName||'')}</div></td>`}<td class="small">${lbl(R_TYPES,r.type)}</td><td>${badge(PRIO,r.impact)}</td><td class="small">${lbl(PARTIES,r.party)}</td><td class="small">${esc(r.ownerName||'—')}</td><td class="small ${riskOverdue(r)?'late':''}">${esc(r.target||'—')}</td><td>${badge(R_STATUS,r.status)}</td></tr>`).join('')}</tbody></table></div>`}
function riskForm(id,engId){const ex=id?RISKS.find(x=>x.id===id):null;const r=ex?{...ex}:{engagementId:engId||'',type:'risk',title:'',description:'',impact:'medium',priority:'medium',ownerName:'',party:'internal',identified:todayStr(),target:dAdd(14),mitigation:'',status:'open',escalation:false,escalationNote:''};
  if(!r.engagementId&&r.clientId)r.engagementId=r.clientId;if(!Object.keys(ENG).length)return toast(L('Create an engagement first.','أنشئ ارتباطاً أولاً.'));const ro=!isOps();
  modal(id?`${r.code||''} ${L('Risk / blocker','خطر / عائق')}`:L('New risk, issue, blocker or dependency','خطر أو مشكلة أو عائق أو اعتمادية جديدة'),`<div class="grid g3" style="gap:10px"><div class="field" style="grid-column:span 2"><label>${L('Title','العنوان')} *</label><input class="txt" id="rf_title" value="${esc(r.title)}"></div><div class="field"><label>${L('Type','النوع')}</label><select class="txt" id="rf_type">${optList(R_TYPES,r.type)}</select></div>
   <div class="field" style="grid-column:span 2"><label>${L('Engagement','الارتباط')}</label>${engPick('rf_engagementId',r.engagementId)}</div><div class="field"><label>${L('Who must act','من عليه التصرف')}</label><select class="txt" id="rf_party">${optList(PARTIES,r.party)}</select></div>
   <div class="field"><label>${L('Impact','التأثير')}</label><select class="txt" id="rf_impact">${optList(PRIO,r.impact)}</select></div><div class="field"><label>${L('Priority','الأولوية')}</label><select class="txt" id="rf_priority">${optList(PRIO,r.priority||'medium')}</select></div><div class="field"><label>${L('Responsible owner','المسؤول')}</label>${ownerInput('rf_ownerName',r.ownerName)}</div>
   <div class="field"><label>${L('Date identified','تاريخ الرصد')}</label><input class="txt" type="date" id="rf_identified" value="${esc(r.identified)}"></div><div class="field"><label>${L('Target resolution','تاريخ الحل المستهدف')}</label><input class="txt" type="date" id="rf_target" value="${esc(r.target)}"></div><div class="field"><label>${L('Status','الحالة')}</label><select class="txt" id="rf_status">${optList(R_STATUS,r.status)}</select></div></div>
   <div class="field"><label>${L('Description','الوصف')}</label><textarea class="txt" id="rf_description" rows="2">${esc(r.description)}</textarea></div><div class="field"><label>${L('Mitigation / resolution action','إجراء المعالجة / الحل')}</label><textarea class="txt" id="rf_mitigation" rows="2">${esc(r.mitigation)}</textarea></div>
   <div class="card" style="background:var(--soft)"><label class="small"><input type="checkbox" id="rf_escalation" ${r.escalation?'checked':''}> <b>${L('Escalate to leadership','تصعيد إلى القيادة')}</b></label><div class="field" style="margin-top:6px"><label>${L('What leadership needs to do','ما المطلوب من القيادة')}</label><input class="txt" id="rf_escalationNote" value="${esc(r.escalationNote||'')}"></div></div>
   ${ex?`<p class="small muted">${L('Identified','رُصد')} ${esc(r.identified)}${r.resolvedAt?` · ${L('Resolved','حُل')} ${esc(String(r.resolvedAt).slice(0,10))}`:''} · ${(r.history||[]).map(h=>`${esc(String(h.at).slice(0,10))} ${esc(h.by)}: ${esc(h.note)}`).join(' · ')}</p>`:''}
   ${ro?'':`<div class="savebar"><button class="btn primary" onclick="riskSave(${id?`'${id}'`:'null'})">💾 ${L('Save','حفظ')}</button>${id?`<button class="btn" onclick="closeModal();actionForm(null,{engagementId:'${r.engagementId}',title:${esc(JSON.stringify(r.title))},priority:'${r.impact}'})">＋ ${L('Action for this','إجراء لهذا')}</button><button class="btn" onclick="riskDelete('${id}')">🗑</button>`:''}</div>`}`)}
async function riskSave(id){const f={};['title','engagementId','type','impact','priority','party','ownerName','identified','target','status','description','mitigation','escalationNote'].forEach(k=>f[k]=$('#rf_'+k).value.trim());f.escalation=$('#rf_escalation').checked;
  if(!f.title)return toast(L('Enter a title.','أدخل العنوان.'));if(f.escalation&&!f.escalationNote)return toast(L('Say what leadership needs to do.','اذكر المطلوب من القيادة.'));
  const e=ENG[f.engagementId],t=nowIso();f.clientId=f.engagementId;f.accountId=e?e.accountId:'';f.clientName=e?accName(e.accountId)||e.org||'':'';f.engName=e?e.name:'';f.updatedAt=t;f.updatedBy=myName();
  try{if(id){const ex=RISKS.find(x=>x.id===id),notes=[];if(ex.status!==f.status)notes.push(`${lbl(R_STATUS,ex.status)} → ${lbl(R_STATUS,f.status)}`);if(ex.impact!==f.impact)notes.push(`${L('impact','التأثير')} ${lbl(PRIO,ex.impact)} → ${lbl(PRIO,f.impact)}`);if(!ex.escalation&&f.escalation){notes.push(L('escalated','تم التصعيد'));f.escalatedAt=t}
      f.resolvedAt=['resolved','closed'].includes(f.status)?(ex.resolvedAt||t):'';f.history=[...(ex.history||[]),...(notes.length?[{at:t,by:myName(),note:notes.join(', ')}]:[])];await DB.collection('risks').doc(id).update(f);audit('risk',id,L('Risk updated','تحديث خطر')+': '+f.title,diffs(ex,f,['status','impact','escalation','target','ownerName']),ctxOf(f.engagementId))}
    else{f.code=mkCode('RSK');f.createdAt=t;f.createdBy=ME.id;f.resolvedAt='';if(f.escalation)f.escalatedAt=t;f.history=[{at:t,by:myName(),note:L('Identified','تم الرصد')}];const r=await DB.collection('risks').add(f);audit('risk',r.id,L('Risk registered','تسجيل خطر')+': '+f.title,[],ctxOf(f.engagementId))}
    toast(L('Saved','تم الحفظ'));closeModal()}catch(err){deny(err)}}
async function riskDelete(id){if(!confirmDel('rk'+id))return;try{await DB.collection('risks').doc(id).delete();audit('risk',id,L('Risk deleted','حذف خطر'),[],{});closeModal();toast(L('Deleted','تم الحذف'))}catch(e){deny(e)}}

/* ---------------- stakeholders & documents ---------------- */
function stakeholderList(a){const cs=a.stakeholders||[];
  return `${btnIf(canEditRec(a),`<div style="margin-bottom:12px"><button class="btn primary" onclick="stakeholderForm('${a.id}')">＋ ${L('Stakeholder','صاحب علاقة')}</button></div>`)}
  ${cs.length?`<div class="card" style="padding:0;overflow:auto"><table class="leads"><thead><tr><th>${L('Name','الاسم')}</th><th>${L('Organisation / department','الجهة / الإدارة')}</th><th>${L('Role','الدور')}</th><th>${L('Contact','التواصل')}</th><th>${L('Engagements','الارتباطات')}</th><th>${L('Relationship owner','مسؤول العلاقة')}</th></tr></thead><tbody>${cs.map((c,i)=>`<tr ${canEditRec(a)?`onclick="stakeholderForm('${a.id}',${i})"`:''}><td><b>${esc(c.name)}</b>${c.primary?' ★':''}</td><td class="small">${esc(c.org||a.name)}${c.dept?`<div class="muted">${esc(c.dept)}</div>`:''}</td><td class="small">${esc(c.role||c.position||'')}</td><td class="small">${c.email?`✉ ${esc(c.email)}<br>`:''}${c.mobile?`📱 <span dir="ltr">${esc(c.mobile)}</span>`:''}${c.commPref?`<div class="muted">${esc(c.commPref)}</div>`:''}</td><td class="small">${(c.engagementIds||[]).map(id=>esc(ENG[id]?.name||'')).join(', ')||L('All','الكل')}</td><td class="small">${esc(c.relOwner||'—')}</td></tr>`).join('')}</tbody></table></div>`:`<div class="empty">${L('No stakeholders yet.','لا يوجد أصحاب علاقة بعد.')}</div>`}`}
function stakeholderForm(aid,i){const a=ACC[aid],c=i!=null?{...a.stakeholders[i]}:{name:'',org:a.name,role:'',dept:'',email:'',mobile:'',engagementIds:[],relOwner:'',commPref:'',notes:'',primary:false};if(c.position&&!c.role)c.role=c.position;
  modal(L('Stakeholder','صاحب العلاقة'),`<div class="grid g2" style="gap:10px">${[['name',L('Name','الاسم')+' *'],['org',L('Organisation','الجهة')],['role',L('Role','الدور')],['dept',L('Department','الإدارة')],['email',L('Email','البريد')],['mobile',L('Mobile','الجوال')],['relOwner',L('Relationship owner (our side)','مسؤول العلاقة (من جانبنا)')],['commPref',L('Communication preference (if known)','تفضيل التواصل (إن عُرف)')]].map(([k,t])=>`<div class="field"><label>${t}</label><input class="txt" id="sk_${k}" value="${esc(c[k]||'')}" ${['email','mobile'].includes(k)?'dir="ltr"':''}></div>`).join('')}</div>
   <div class="field"><label>${L('Relevant engagements','الارتباطات ذات الصلة')}</label><div class="chk">${accEngs(aid).map(e=>`<label><input type="checkbox" class="sk_e" value="${e.id}" ${(c.engagementIds||[]).includes(e.id)?'checked':''}> ${esc(e.name||e.code)}</label>`).join('')||'—'}</div></div>
   <div class="field"><label>${L('Engagement notes','ملاحظات الارتباط')}</label><textarea class="txt" id="sk_notes" rows="2">${esc(c.notes||'')}</textarea></div><label class="small"><input type="checkbox" id="sk_primary" ${c.primary?'checked':''}> ${L('Primary contact','جهة الاتصال الرئيسية')}</label>
   <p class="small muted">${L('Record only facts the person has shared or that are needed to work together — no personal profiling.','سجّل فقط الحقائق المشتركة أو اللازمة للعمل معاً — دون تصنيف شخصي.')}</p>
   <div class="savebar"><button class="btn primary" onclick="stakeholderSave('${aid}',${i??'null'})">💾 ${L('Save','حفظ')}</button>${i!=null?`<button class="btn" onclick="stakeholderSave('${aid}',${i},true)">🗑 ${L('Remove','إزالة')}</button>`:''}</div>`)}
async function stakeholderSave(aid,i,del){if(del&&!confirmDel('sk'+aid+i))return;const a=clone(ACC[aid]);a.stakeholders=a.stakeholders||[];let nm='';
  if(del){nm=a.stakeholders[i].name;a.stakeholders.splice(i,1)}else{const c={...(i!=null?a.stakeholders[i]:{})};['name','org','role','dept','email','mobile','relOwner','commPref','notes'].forEach(k=>c[k]=$('#sk_'+k).value.trim());c.engagementIds=[...document.querySelectorAll('.sk_e:checked')].map(x=>x.value);c.primary=$('#sk_primary').checked;if(!c.name)return toast(L('Enter a name.','أدخل الاسم.'));nm=c.name;if(c.primary)a.stakeholders.forEach(x=>x.primary=false);if(i!=null)a.stakeholders[i]=c;else a.stakeholders.push(c)}
  if(await saveSafe(saveAcc,a,L('Saved','تم الحفظ'))){audit('account',aid,(del?L('Stakeholder removed','إزالة صاحب علاقة'):L('Stakeholder saved','حفظ صاحب علاقة'))+': '+nm,[],{accountId:aid});closeModal()}}
function docsView(e){const ds=e.documents||[];return `${btnIf(canEditRec(e),`<div style="margin-bottom:12px"><button class="btn primary" onclick="docForm('${e.id}')">＋ ${L('Document link','رابط مستند')}</button></div>`)}
  ${ds.length?`<div class="card" style="padding:0;overflow:auto"><table class="leads"><thead><tr><th>${L('Document','المستند')}</th><th>${L('Type','النوع')}</th><th>${L('Added','أُضيف')}</th></tr></thead><tbody>${ds.map(d=>`<tr><td><a href="${esc(d.url)}" target="_blank" rel="noopener">${esc(d.title)}</a></td><td class="small">${esc(d.kind||'')}</td><td class="small muted">${esc(String(d.at).slice(0,10))} · ${esc(d.by)}</td></tr>`).join('')}</tbody></table></div>`:`<div class="empty">${L('No documents yet. Add links to SharePoint, Teams or Drive files.','لا توجد مستندات بعد. أضف روابط ملفات SharePoint أو Teams أو Drive.')}</div>`}`}
function docForm(id){modal(L('Document link','رابط مستند'),`<div class="field"><label>${L('Title','العنوان')}</label><input class="txt" id="dk_t"></div><div class="field"><label>${L('Link (URL)','الرابط')}</label><input class="txt" id="dk_u" dir="ltr" placeholder="https://"></div><div class="field"><label>${L('Type','النوع')}</label><input class="txt" id="dk_k" placeholder="${L('e.g. Requirements, Proposal, Minutes','مثال: متطلبات، عرض، محضر')}"></div><div class="savebar"><button class="btn primary" onclick="docSave('${id}')">💾 ${L('Save','حفظ')}</button></div>`)}
async function docSave(id){const t=$('#dk_t').value.trim(),u=$('#dk_u').value.trim();if(!t||!/^https?:\/\//.test(u))return toast(L('Enter a title and a full link starting with https://','أدخل العنوان ورابطاً كاملاً يبدأ بـ https://'));
  const e=clone(ENG[id]);e.documents=[...(e.documents||[]),{title:t,url:u,kind:$('#dk_k').value.trim(),at:nowIso(),by:myName()}];if(await saveSafe(saveEng,e,L('Saved','تم الحفظ'))){audit('engagement',id,L('Document added','إضافة مستند')+': '+t,[],ctxOf(id));closeModal()}}

/* ---------------- engagement timeline (from source records + audit) ---------------- */
function engTimeline(e){const ev=[];
  (e.activities||[]).forEach(a=>ev.push({at:a.d+(a.time?' '+a.time:''),icon:(EACT.find(t=>t[0]===a.type)||[])[3]||'•',t:`${a.status==='planned'?L('Planned','مخطط')+': ':''}${a.title}`,s:a.decisions?L('Decisions','القرارات')+': '+a.decisions:'',go:`go('eng','eng','${e.id}~activities')`}));
  (e.stageHistory||[]).forEach(h=>ev.push({at:h.date||String(h.at).slice(0,10),icon:'➜',t:h.from!==h.to?`${L('Stage','المرحلة')}: ${h.from?stageLabel(h.from)+' → ':''}${stageLabel(h.to)}`:h.note,s:h.from!==h.to?h.note:'',by:h.by}));
  (e.legacyStageNotes||[]).forEach(n=>ev.push({at:n.d,icon:'⇢',t:n.text,s:L('Sales stage history from the lead','سجل مراحل البيع من الفرصة')}));
  engActions(e.id).forEach(a=>{ev.push({at:String(a.createdAt).slice(0,10),icon:'✚',t:`${L('Action created','إجراء جديد')}: ${a.title}`,s:a.ownerName,go:`actionView('${a.id}')`});if(a.status==='done'&&a.completedAt)ev.push({at:String(a.completedAt).slice(0,10),icon:'✔',t:`${L('Action completed','اكتمل الإجراء')}: ${a.title}`,s:a.evidence,go:`actionView('${a.id}')`})});
  engRisks(e.id).forEach(r=>{ev.push({at:r.identified||String(r.createdAt).slice(0,10),icon:'⚠',t:`${lbl(R_TYPES,r.type)}: ${r.title}`,s:lbl(PRIO,r.impact),go:`riskForm('${r.id}')`});if(r.escalatedAt)ev.push({at:String(r.escalatedAt).slice(0,10),icon:'⬆',t:`${L('Escalated','تم التصعيد')}: ${r.title}`,s:r.escalationNote,go:`riskForm('${r.id}')`});if(r.resolvedAt)ev.push({at:String(r.resolvedAt).slice(0,10),icon:'✓',t:`${L('Resolved','تم الحل')}: ${r.title}`,go:`riskForm('${r.id}')`})});
  engDecs(e.id).forEach(d=>{if(d.status==='decided')ev.push({at:d.decidedAt||String(d.updatedAt).slice(0,10),icon:'⚖',t:`${L('Decision','قرار')}: ${d.title}`,s:d.final,go:`decisionForm('${d.id}')`})});
  engReqs(e.id).forEach(r=>(r.history||[]).slice(1).forEach(h=>ev.push({at:String(h.at).slice(0,10),icon:'📋',t:`${L('Requirement','متطلب')}: ${r.title}`,s:h.note,go:`reqForm('${r.id}')`})));
  if(e.latestUpdate)ev.push({at:String(e.latestUpdate.at).slice(0,10),icon:'📝',t:L('Status update','تحديث الوضع'),s:e.latestUpdate.text});
  ev.sort((a,b)=>String(b.at).localeCompare(String(a.at)));
  return ev.length?`<div class="tl">${ev.map(x=>`<div class="tl-i" ${x.go?`onclick="${x.go}" style="cursor:pointer"`:''}><span class="tl-d">${esc(x.at)}</span><span class="tl-ic">${x.icon}</span><div><b>${esc(x.t)}</b>${x.s?`<div class="small muted" style="white-space:pre-wrap">${esc(String(x.s).slice(0,300))}</div>`:''}</div></div>`).join('')}</div>`:`<div class="empty">${L('Nothing recorded yet.','لا يوجد شيء مسجل بعد.')}</div>`}

/* ---------------- audit trail ---------------- */
let AUF='';
function auditView(){const list=AUDIT.filter(x=>!AUF||x.accountId===AUF);
  return `<div class="page-hd"><div><h1>${L('Audit trail','سجل التدقيق')}</h1><p class="muted">${L('Who changed what and when, with the previous and new value. Entries cannot be edited or deleted. Latest 400 shown.','من غيّر ماذا ومتى، مع القيمة السابقة والجديدة. لا يمكن تعديل القيود أو حذفها. تُعرض آخر 400.')}</p></div></div>
  <div class="filters"><select class="txt" onchange="AUF=this.value;render()"><option value="">${L('All accounts','كل الحسابات')}</option>${Object.values(ACC).map(a=>`<option value="${a.id}" ${AUF===a.id?'selected':''}>${esc(a.name)}</option>`).join('')}</select></div>
  ${list.length?`<div class="card" style="padding:0;overflow:auto"><table class="leads"><thead><tr><th>${L('When','متى')}</th><th>${L('Who','من')}</th><th>${L('What','ماذا')}</th><th>${L('Change','التغيير')}</th></tr></thead><tbody>${list.map(x=>`<tr><td class="small">${dt(x.at)}</td><td class="small">${esc(x.byName||'')}</td><td class="small"><b>${esc(x.summary||'')}</b><div class="muted">${esc(x.entity)} · ${esc(accName(x.accountId))}</div></td><td class="small">${(x.changes||[]).map(c=>`<div><b>${esc(c.f)}</b>: <span class="muted">${esc(c.prev)||'∅'}</span> → ${esc(c.next)||'∅'}</div>`).join('')}</td></tr>`).join('')}</tbody></table></div>`:`<div class="empty">${L('No changes recorded yet.','لم تُسجّل تغييرات بعد.')}</div>`}`}

/* ---------------- lifecycle configuration (Leadership) ---------------- */
let SCD=null;
function stageConfigView(){if(realRole!=='leadership')return `<div class="card empty">🔒</div>`;
  if(!SCD)SCD=JSON.parse(JSON.stringify({stages:allStages(),settings:settings()}));
  return `<div class="page-hd"><div><h1>${L('Lifecycle stages & standards','مراحل دورة الحياة والمعايير')}</h1><p class="muted">${L('Rename stages, change their order, edit exit criteria or switch a stage off. Changes apply to new moves; past stage history keeps the names it was recorded with.','أعد تسمية المراحل أو غيّر ترتيبها أو عدّل معايير الخروج أو أوقف مرحلة. تنطبق التغييرات على الحركات الجديدة؛ ويحتفظ سجل المراحل السابق بأسمائه.')}</p></div><div style="display:flex;gap:8px"><button class="btn" onclick="SCD=null;render()">↺ ${L('Discard','تجاهل')}</button><button class="btn primary" onclick="stageCfgSave()">💾 ${L('Save','حفظ')}</button></div></div>
  <div class="card" style="margin-bottom:12px"><div class="field" style="max-width:360px"><label>${L('Flag an engagement At risk after this many days without activity (when nothing is scheduled)','اعتبار الارتباط معرضاً للخطر بعد هذا العدد من الأيام دون نشاط (إن لم يُجدول شيء)')}</label><input class="txt" type="number" min="1" max="90" value="${SCD.settings.inactiveDays}" onchange="SCD.settings.inactiveDays=Math.max(1,+this.value||14)"></div></div>
  ${SCD.stages.map((s,i)=>`<div class="card pe-block"><div style="display:flex;gap:10px;align-items:center;flex-wrap:wrap"><b>${i+1}.</b><input class="txt" style="flex:1;min-width:180px" value="${esc(s.en)}" onchange="SCD.stages[${i}].en=this.value"><input class="txt" dir="rtl" style="flex:1;min-width:180px" value="${esc(s.ar)}" onchange="SCD.stages[${i}].ar=this.value"><input type="color" value="${esc(s.c)}" onchange="SCD.stages[${i}].c=this.value"><label class="small"><input type="checkbox" ${s.active!==false?'checked':''} onchange="SCD.stages[${i}].active=this.checked"> ${L('in use','مستخدمة')}</label><button class="btn sm" ${i?'':'disabled'} onclick="[SCD.stages[${i-1}],SCD.stages[${i}]]=[SCD.stages[${i}],SCD.stages[${i-1}]];render()">↑</button><button class="btn sm" ${i<SCD.stages.length-1?'':'disabled'} onclick="[SCD.stages[${i+1}],SCD.stages[${i}]]=[SCD.stages[${i}],SCD.stages[${i+1}]];render()">↓</button></div>
   <div class="field" style="margin-top:8px"><label>${L('Exit criteria — one per line, "English | Arabic"','معايير الخروج — معيار في كل سطر، "إنجليزي | عربي"')}</label><textarea class="txt" rows="3" onchange="SCD.stages[${i}].crit=this.value.split('\\n').map(x=>x.split('|').map(y=>y.trim())).filter(x=>x[0]).map(x=>[x[0],x[1]||x[0]])">${esc((s.crit||[]).map(c=>c[0]+' | '+c[1]).join('\n'))}</textarea></div></div>`).join('')}
  <button class="btn" onclick="SCD.stages.push({id:'s'+Date.now().toString(36),en:'New stage',ar:'مرحلة جديدة',c:'#8E2DBA',purpose:['',''],crit:[]});render()">＋ ${L('Add stage','إضافة مرحلة')}</button>`}
async function stageCfgSave(){try{await DB.collection('config').doc('stages').set({json:JSON.stringify({stages:SCD.stages,settings:SCD.settings}),updatedAt:nowIso(),updatedBy:myName()});STAGECFG={stages:SCD.stages,settings:SCD.settings};audit('config','stages',L('Lifecycle stages updated','تحديث مراحل دورة الحياة'),[],{});SCD=null;toast(L('Saved','تم الحفظ'));render()}catch(e){deny(e)}}
